import { readdirSync } from 'node:fs';
import { createDb, read } from '../tools/baseline-lib.mjs';

const db = await createDb();

const admin = '11111111-1111-1111-1111-111111111111';
const user = '22222222-2222-2222-2222-222222222222';
const moderator = '33333333-3333-3333-3333-333333333333';
const missing = '99999999-9999-9999-9999-999999999999';
const tester = '44444444-4444-4444-4444-444444444444';
const campaign = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';
const report = 'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb';

const calls = [
  ['adjust credits', `select public.admin_adjust_credits('${user}',1,'audit')`],
  ['lock user', `select public.admin_set_user_lock('${user}',true,'audit')`],
  ['contact list', `select public.admin_get_contact_reports()`],
  ['contact reply', `select public.admin_reply_contact_report('${missing}','audit')`],
  ['contact status', `select public.admin_update_report_status('${missing}',true)`],
  ['notification', `select public.admin_send_notification('${user}','audit','audit','admin')`],
  ['app configuration', `select public.admin_update_app_config(1,28,'1.0.8',false)`],
  ['home stats read', `select public.admin_get_home_stats_config()`],
  ['home stats write', `select public.admin_set_home_stats_cycle(2,null)`],
  ['daily task configuration', `select public.admin_get_daily_task_config()`],
  ['daily task list', `select public.admin_list_daily_task_policies()`],
  ['daily task history', `select public.admin_get_daily_task_policy_history()`],
  ['daily task schedule', `select public.admin_schedule_daily_task_policy(3,current_date+1,'audit','invalid')`],
  ['daily task cancellation', `select public.admin_cancel_daily_task_policy(current_date+1,'audit','invalid')`],
  ['campaign pause', `select public.admin_pause_campaign('${missing}','audit')`],
  ['campaign resume', `select public.admin_resume_campaign('${missing}')`],
  ['campaign delete', `select public.admin_delete_campaign('${missing}','audit')`],
];

async function asActor(uid, sql, role = 'authenticated') {
  await db.exec(`savepoint sp_actor; select set_config('request.jwt.claim.sub','${uid ?? ''}',true); set local role ${role};`);
  try {
    const res = await db.query(sql);
    await db.exec(`release savepoint sp_actor;`);
    return res;
  } catch (err) {
    await db.exec(`rollback to savepoint sp_actor;`);
    throw err;
  } finally {
    try {
      await db.exec(`reset role; select set_config('request.jwt.claim.sub','',true);`);
    } catch {
      // ignore if aborted
    }
  }
}

async function test(name, fn) {
  await db.exec('begin');
  try {
    await fn();
    console.log(`PASS: ${name}`);
  } catch (e) {
    console.error(`FAIL: ${name}`, e.message);
    throw e;
  } finally {
    await db.exec('rollback');
  }
}

const targetMigration = process.env.UP_TO_MIGRATION ? Number(process.env.UP_TO_MIGRATION) : 999;
const migrationFiles = readdirSync(new URL('../migrations/', import.meta.url))
  .filter(n => /^\d+.*\.sql$/.test(n) && Number(n.slice(0, 3)) <= targetMigration)
  .sort();

console.log(`=== LOADING ACTIVE MIGRATIONS (UP TO ${targetMigration}) ===`);
for (const name of migrationFiles) {
  console.log(`Applying ${name}...`);
  await db.exec(read('supabase/migrations/' + name));
}

// Seed baseline test data
await db.exec(`
  insert into auth.users(id, email) values
    ('${admin}', 'admin@fixture.invalid'),
    ('${user}', 'member@fixture.invalid'),
    ('${moderator}', 'mod@fixture.invalid'),
    ('${tester}', 'tester@fixture.invalid')
  on conflict (id) do nothing;

  update public.profiles set role = 'admin', is_locked = false where id = '${admin}';
  update public.profiles set role = 'moderator', is_locked = false where id = '${moderator}';
  update public.profiles set role = 'member', is_locked = false, credits = 5 where id = '${user}';
  update public.profiles set role = 'member', is_locked = false where id = '${tester}';

  insert into public.campaigns(id, owner_id, app_name, package_name, status)
  values ('${campaign}', '${user}', 'Admin audit fixture', 'invalid.fixture.admin', 'open')
  on conflict (id) do nothing;

  insert into public.campaign_members(campaign_id, user_id)
  values ('${campaign}', '${tester}')
  on conflict (campaign_id, user_id) do nothing;

  insert into public.tester_reports(id, campaign_id, user_id, status, content, created_at)
  values ('${report}', '${campaign}', '${tester}', 'pending', 'Audit fixture', now())

-- ============================================================================
-- Migration 069: Admin Flow Audit & Hardening
--
-- 1. Effective credit delta matching ledger and return amount with input/overflow validation
-- 2. Fail-closed unlocked admin verification across all admin RPCs
-- 3. Target existence validation for user lock (prevent phantom success)
-- 4. Fail-closed unlocked caller check for report approval/rejection (admin/moderator/owner)
-- 5. Lock-aware can_manage in get_campaign_detail (excluding locked staff & locked owner)
-- 6. Hardened RLS policies for app_configs UPDATE, campaigns DELETE/SELECT, and reports
-- 7. Revoke excessive TRUNCATE & TRIGGER capabilities from client roles (anon, authenticated, public)
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. admin_adjust_credits: fix ledger overdraft mismatch, validate null/0/overflow
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_adjust_credits(
    p_target_user_id uuid,
    p_amount integer,
    p_reason text DEFAULT 'Điều chỉnh bởi Admin'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_caller_locked boolean;
    v_current_credits int;
    v_calc_balance bigint;
    v_new_balance int;
    v_effective_amount int;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role, coalesce(is_locked, false)
    into v_caller_role, v_caller_locked
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is null or lower(v_caller_role) != 'admin' or v_caller_locked = true then
        raise exception 'PERMISSION_DENIED: Chỉ Quản trị viên chưa bị khóa mới có quyền điều chỉnh Credit';
    end if;

    if p_target_user_id is null then
        raise exception 'TARGET_USER_REQUIRED';
    end if;

    if p_amount is null or p_amount = 0 then
        raise exception 'INVALID_AMOUNT: Số lượng credit phải khác 0';
    end if;

    select credits into v_current_credits
    from public.profiles
    where id = p_target_user_id
    for update;

    if not found or v_current_credits is null then
        raise exception 'USER_NOT_FOUND';
    end if;

    v_calc_balance := v_current_credits::bigint + p_amount::bigint;
    if v_calc_balance > 2147483647 then
        raise exception 'CREDIT_OVERFLOW: Số dư vượt quá giới hạn tối đa';
    end if;

    if v_calc_balance < 0 then
        v_new_balance := 0;
    else
        v_new_balance := v_calc_balance::integer;
    end if;

    v_effective_amount := v_new_balance - v_current_credits;

    update public.profiles
    set credits = v_new_balance
    where id = p_target_user_id;

    insert into public.credit_logs (user_id, amount, action, note, balance)
    values (
        p_target_user_id,
        v_effective_amount,
        case when p_amount >= 0 then 'admin_grant' else 'admin_deduct' end,
        coalesce(nullif(trim(p_reason), ''), case when p_amount >= 0 then 'Admin tặng Credit' else 'Admin trừ Credit' end),
        v_new_balance
    );

    return jsonb_build_object(
        'success', true,
        'user_id', p_target_user_id,
        'previous_credits', v_current_credits,
        'new_credits', v_new_balance,
        'amount', v_effective_amount
    );
end;

$function$;

-- ----------------------------------------------------------------------------
-- 2. admin_set_user_lock: validate target existence and unlocked admin caller
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_set_user_lock(
    p_target_user_id uuid,
    p_locked boolean,
    p_reason text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_caller_locked boolean;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role, coalesce(is_locked, false)
    into v_caller_role, v_caller_locked
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is null or lower(v_caller_role) != 'admin' or v_caller_locked = true then
        raise exception 'PERMISSION_DENIED: Chỉ Quản trị viên chưa bị khóa mới có quyền khóa/mở khóa tài khoản';
    end if;

    if p_target_user_id is null then
        raise exception 'TARGET_USER_REQUIRED';
    end if;

    if p_target_user_id = v_caller_id and p_locked = true then
        raise exception 'CANNOT_LOCK_SELF: Không thể tự khóa tài khoản của chính mình';
    end if;

    update public.profiles
    set is_locked = p_locked
    where id = p_target_user_id;

    if not found then
        raise exception 'USER_NOT_FOUND';
    end if;

    return jsonb_build_object(
        'success', true,
        'user_id', p_target_user_id,
        'is_locked', p_locked
    );
end;
$function$;

-- ----------------------------------------------------------------------------
-- 3. admin_get_contact_reports: guard unlocked admin
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_get_contact_reports(p_status text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
    v_caller_id uuid := auth.uid();
    v_caller_role text;
    v_caller_locked boolean;
    v_result jsonb;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role, coalesce(is_locked, false)
    into v_caller_role, v_caller_locked
    from public.profiles
    where id = v_caller_id;

    if v_caller_role is null or lower(v_caller_role) != 'admin' or v_caller_locked = true then
        raise exception 'NOT_ADMIN';
    end if;

    select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb)
    into v_result
    from (
        select
            r.id,
            r.user_id,
            r.category,
            r.message,
            r.app_version,
            r.platform,
            r.device_model,
            r.status,
            r.admin_reply,
