CREATE OR REPLACE FUNCTION public.retry_failed_mission_settlements(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_job record;
    v_success_count int := 0;
    v_res jsonb;
begin
    for v_job in
        select id, report_id
        from public.mission_settlement_jobs
        where status in ('pending', 'failed')
          and attempt_count < 10
          and next_attempt_at <= now()
        order by next_attempt_at asc, created_at asc
        limit p_limit
        for update skip locked
    loop
        v_res := public._settle_mission_reward(v_job.report_id);
        if coalesce((v_res->>'settled')::boolean, false) and coalesce((v_res->>'paid')::boolean, false) then
            v_success_count := v_success_count + 1;
        end if;
    end loop;

    return v_success_count;
end;
