    v_owner_warned boolean := false;
    v_tester_warning_msg text := null;
    v_owner_warning_msg text := null;
    v_is_tester_locked boolean := false;
    v_is_owner_locked boolean := false;
    v_tester_today_rejections int := 0;
    v_tester_weekly_warnings int := 0;
    v_owner_today_rejections int := 0;
    v_owner_weekly_warnings int := 0;
    v_vn_today date := (clock_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
    v_msg_tester text := 'Bạn bị từ chối 3 báo cáo trong ngày hôm nay.';
    v_msg_owner text := 'Bạn đã từ chối 5 báo cáo của tester trong ngày hôm nay.';
    v_ci record;
    v_final_reason_code text;
    v_provisional_granted int;
    v_provisional_clawed int;
begin
    if v_caller_id is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    select role, coalesce(is_locked, false)
    into v_caller_role, v_caller_locked
    from public.profiles
    where id = v_caller_id;

    if v_caller_locked = true then
        raise exception 'ACCOUNT_LOCKED: Tài khoản của bạn đang bị khóa, không thể từ chối báo cáo';
    end if;

    select * into v_report
    from public.tester_reports
    where id = p_report_id
    for update;

    if not found or v_report.id is null then
        raise exception 'REPORT_NOT_FOUND';
    end if;

    if v_report.status <> 'pending' then
        raise exception 'REPORT_NOT_PENDING';
    end if;

    select * into v_camp
    from public.campaigns
    where id = v_report.campaign_id;

    if not found or v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;

    if v_caller_role in ('admin', 'moderator') then
        v_is_staff := true;
    elsif v_camp.owner_id = v_caller_id then
        v_is_staff := false;
    else
        raise exception 'PERMISSION_DENIED';
    end if;

    v_provisional_granted := coalesce(v_report.provisional_granted_credits, 2);
    v_provisional_clawed := coalesce(v_report.provisional_clawed, 2);

    select credits into v_tester_bal
    from public.profiles
    where id = v_report.user_id
    for update;

    if v_tester_bal is null then
        raise exception 'TESTER_NOT_FOUND';
    end if;

    v_deduct := least(v_tester_bal, v_provisional_clawed);
    v_new_balance := v_tester_bal - v_deduct;

    update public.profiles
    set credits = v_new_balance
    where id = v_report.user_id;

    if v_deduct > 0 then
        insert into public.credit_logs (user_id, amount, action, note, balance, metadata)
        values (
            v_report.user_id,

        -v_deduct,
        'report_rejected',
        format('Thu hồi %s Credit do báo cáo bị từ chối (%s)', v_deduct, v_camp.app_name),
        v_new_balance,
